/*
   Image du projet.
   Chaque image est automatiquement en 64x64
   grâce au CSS.
*/

const iimg = i => {

  if (i.img) {

    return `
      <img
        class="itemimg"
        src="${i.img}"
        alt="${i.n}"
        width="64"
        height="64"
      >
    `;

  }

  return `
    <div
      class="itemimg placeholder"
      aria-hidden="true"
    ></div>
  `;
};


/*
   Création d'un projet.

   Résultat :

   [ IMAGE 64x64 ] [ TITRE
                     DESCRIPTION ]
*/

const item = i => {

  const content = `

    ${iimg(i)}

    <div class="itemcontent">

      <h3>
        ${i.n}
      </h3>

      <p>
        ${i.d}
      </p>

    </div>

  `;


  /*
     Projet avec lien
  */

  if (i.url) {

    return `
      <a
        class="item link"
        href="${i.url}"
        target="_blank"
        rel="noopener"
      >
        ${content}
      </a>
    `;

  }


  /*
     Projet sans lien
  */

  return `
    <div class="item">
      ${content}
    </div>
  `;
};


