/* ============================================================
   NAVIGATION
   ============================================================ */

const btns =
  document.querySelectorAll(".btn");


/*
   Cliquer sur le logo retourne à l'accueil
*/

document.querySelector(".logo").onclick = () => {

  btns[0].click();

};


/*
   Navigation
*/

btns.forEach(b => {

  b.onclick = () => {

    btns.forEach(x => {

      x.classList.toggle(
        "active",
        x === b
      );

    });


    const cur =
      document.querySelector("section.show");

    const next =
      document.getElementById(b.dataset.t);


    if (cur === next) {
      return;
    }


    cur.classList.remove("in");


    setTimeout(() => {

      cur.classList.remove("show");

      next.classList.add("show");

      void next.offsetWidth;

      next.classList.add("in");

    }, 300);

  };

});


/*
   Animation initiale
*/

document
  .getElementById("home")
  .classList.add("in");


/* ============================================================
   MODAL MODELES 3D
   ============================================================ */

const modal =
  document.getElementById("modal");

const mbox =
  document.getElementById("mbox");


/*
   Ouvrir un modèle
*/

function openModel(m) {

  const shots = (

    m.shots && m.shots.length

      ? m.shots.map(
          u =>
            `
              <img
                src="${u}"
                alt="Screenshot ${m.n}"
              >
            `
        )

      : [1, 2, 3].map(
          () =>
            `<div class="ph"></div>`
        )

  ).join("");


  mbox.innerHTML = `

    <button
      class="x"
      id="mx"
      aria-label="Fermer"
    >
      ×
    </button>

    <h2>
      ${m.n}
    </h2>

    <p>
      ${m.d}
    </p>

    <div class="shots">
      ${shots}
    </div>

    <button
      class="dl"
      id="dl"
    >
      ⬇ Download
    </button>

    <span
      class="msg"
      id="dmsg"
    ></span>

  `;


  /*
     Bouton fermer
  */

  document
    .getElementById("mx")
    .onclick = closeModal;


  /*
     Bouton téléchargement
  */

  document
    .getElementById("dl")
    .onclick = async () => {

      const msg =
        document.getElementById("dmsg");


      try {

        const url = m.file || m.fname;

        if (!url) {
          msg.textContent = "Aucun fichier disponible au téléchargement.";
          return;
        }

        msg.textContent = "Téléchargement en cours…";

        const response = await fetch(url);
        if (!response.ok) {
          throw new Error("Échec du téléchargement");
        }

        const blob = await response.blob();
        const link = document.createElement("a");
        const downloadUrl = URL.createObjectURL(blob);
        link.href = downloadUrl;
        link.download = m.filename || `${m.n}.zip`;
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(downloadUrl);
        msg.textContent = "";

      }


      catch (e) {

        msg.textContent = "Téléchargement impossible.";

      }

    };


  /*
     Afficher le popup
  */

  modal.classList.add("open");

}


/* ============================================================
   FERMETURE DU MODAL
   ============================================================ */

/*
   Fermer le popup
*/

function closeModal() {

  modal.classList.remove("open");

}


/*
   Cliquer sur le fond du popup
*/

modal.onclick = e => {

  if (e.target === modal) {

    closeModal();

  }

};


/*
   Touche Escape
*/

document.addEventListener(
  "keydown",
  e => {

    if (e.key === "Escape") {

      closeModal();

    }

  }
);


/* ============================================================
   CLIC SUR LES MODELES
   ============================================================ */

document
  .getElementById("mg")
  .onclick = e => {

    const c =
      e.target.closest(".card");


    if (c) {

      openModel(
        models[+c.dataset.i]
      );

    }

  };
